use super::*;

/// Top-level items (fn/struct/enum/const/static/type/union) declared WITHOUT a visibility modifier —
/// PRIVATE to the module. The caller (`cohesion_reason`) keeps only the ones that are NOT themselves
/// extractable leaves — a private type or an impure/stateful private helper — because a leaf that reaches
/// that kind of item is entangled with parent complexity that stays behind. A private item that is itself
/// a pure leaf extracts alongside the others, so referencing it is an inter-leaf call, not coupling.
pub(crate) fn private_item_names(root: Node, src: &[u8]) -> std::collections::HashSet<String> {
    let mut names = std::collections::HashSet::new();
    let mut cursor = root.walk();
    for child in root.children(&mut cursor) {
        if !matches!(
            child.kind(),
            "function_item" | "struct_item" | "enum_item" | "const_item" | "static_item" | "type_item" | "union_item"
        ) {
            continue;
        }
        let mut cc = child.walk();
        let has_vis = child.children(&mut cc).any(|n| n.kind() == "visibility_modifier");
        if has_vis {
            continue;
        }
        if let Some(nm) = child.child_by_field_name("name") {
            names.insert(nm.utf8_text(src).unwrap_or_default().to_string());
        }
    }
    names
}
